import React, { useState } from 'react';
import { User, MapPin, Search, X, FileText, AlertOctagon, Calendar, CreditCard, ChevronRight, Fingerprint, Clock, ShieldCheck, Phone, CheckCircle2 } from 'lucide-react';

const CitizensTab = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState(null);
  const [activeFilter, setActiveFilter] = useState('PROFILE');

  // --- MOCK DATA ENGINE ---
  const citizens = [
    { id: 'CZ-8821', name: 'ARJUN MEHTA', area: 'GANDHI_NAGAR', zone: 'ZONE_A', status: 'ACTIVE', phone: '+91 98XXX XXXXX', joined: '12_JAN_2025' },
    { id: 'CZ-4412', name: 'SARA KHAN', area: 'SILICON_VALLEY', zone: 'ZONE_C', status: 'OVERDUE', phone: '+91 88XXX XXXXX', joined: '05_FEB_2024' },
    { id: 'CZ-9003', name: 'VIKRAM SINGH', area: 'OLD_TOWN', zone: 'ZONE_B', status: 'ACTIVE', phone: '+91 77XXX XXXXX', joined: '22_NOV_2024' },
  ];

  const citizenStats = {
    reports: [
      { id: 'REP-102', type: 'OVERFLOW', date: '20 MAR', status: 'RESOLVED' },
      { id: 'REP-099', type: 'MISSED_PCK', date: '15 MAR', status: 'PENDING' },
    ],
    penalties: [
      { id: 'PNL-44', reason: 'MIXED_WASTE', amount: '₹500', date: '10 MAR' },
    ],
    schedules: [
      { day: 'MON', time: '08:00 AM', type: 'DRY' },
      { day: 'WED', time: '08:00 AM', type: 'WET' },
      { day: 'FRI', time: '09:30 AM', type: 'RECYCLE' },
    ],
    subscription: { plan: 'PREMIUM_ULTRA', price: '₹1,200/mo', expiry: 'APR 2026' }
  };

  return (
    <div className="w-full h-full flex flex-col gap-4 font-black italic uppercase tracking-tighter select-none">

      {/* 🔍 HEADER (Lemon Yellow) */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-[#FFF24D] p-4 rounded-[24px] border-[3px] border-[#47510B] shadow-[4px_4px_0_0_#47510B]">
        <div className="flex items-center gap-3">
          <Fingerprint size={28} className="text-[#47510B]" />
          <h1 className="text-xl leading-none">REGISTRY_DATABASE</h1>
        </div>
        <div className="relative w-full md:w-72">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#47510B]/30" size={16} />
          <input 
            type="text" 
            placeholder="FILTER_RECORDS..." 
            className="w-full bg-white border-[3px] border-[#47510B] rounded-xl p-2 pl-10 text-[10px] outline-none shadow-[2px_2px_0_0_#47510B]"
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* 📋 LIST GRID: pb-40 solves the cut-off issue */}
      <div className="flex-grow overflow-y-auto pr-2 pb-40 custom-scrollbar grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
        {citizens.map(c => (
          <div 
            key={c.id} 
            onClick={() => setSelectedCitizen(c)} 
            className="bg-white border-[3px] border-[#47510B] p-4 rounded-[24px] shadow-[3px_3px_0_0_#47510B] hover:translate-x-1 hover:bg-[#FDFAD8] transition-all cursor-pointer flex justify-between items-center group"
          >
            <div className="min-w-0">
              <p className="text-[9px] text-[#CAD23C] mb-0.5">{c.id}</p>
              <h3 className="text-lg truncate leading-none mb-1">{c.name}</h3>
              <p className="text-[9px] opacity-40">{c.area}</p>
            </div>
            <ChevronRight size={18} className="text-[#47510B] opacity-20 group-hover:opacity-100 group-hover:translate-x-1 transition-all" />
          </div>
        ))}
      </div>

      {/* 🏗️ REFINED MODAL (Optimized Size) */}
      {selectedCitizen && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#47510B]/60 backdrop-blur-sm animate-in fade-in duration-200" onClick={() => setSelectedCitizen(null)} />

          <div className="relative w-full max-w-3xl h-[75vh] bg-[#FDFAD8] border-[5px] border-[#47510B] rounded-[40px] shadow-[12px_12px_0_0_#000] overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">

            {/* COMPACT MODAL HEADER (Grassy Green) */}
            <div className="bg-[#47510B] p-5 text-white flex justify-between items-center shrink-0">
                <div className="flex gap-4 items-center">
                    <div className="w-12 h-12 bg-[#FFF24D] rounded-xl flex items-center justify-center text-[#47510B] border-2 border-white">
                        <User size={28} />
                    </div>
                    <div>
                        <p className="text-[9px] text-[#CAD23C]">ID: {selectedCitizen.id}</p>
                        <h2 className="text-2xl leading-none">{selectedCitizen.name}</h2>
                    </div>
                </div>
                <button onClick={() => setSelectedCitizen(null)} className="hover:bg-[#AB1717] p-2 rounded-xl transition-all">
                  <X size={24} />
                </button>
            </div>

            {/* SLIM TAB NAV (Blue Linen) */}
            <div className="bg-[#A1AED1] p-1.5 flex gap-1.5 overflow-x-auto no-scrollbar shrink-0 border-b-[3px] border-[#47510B]">
              {['PROFILE', 'REPORTS', 'PENALTIES', 'SCHEDULES', 'SUBS'].map(id => (
                <button 
                  key={id}
                  onClick={() => setActiveFilter(id)}
                  className={`px-4 py-2 rounded-lg text-[9px] font-black transition-all border-2 ${activeFilter === id ? 'bg-[#FFF24D] text-[#47510B] border-[#47510B]' : 'text-[#47510B]/50 border-transparent hover:text-[#47510B]'}`}
                >
                  {id}
                </button>
              ))}
            </div>

            {/* MODAL CONTENT AREA */}
            <div className="flex-grow p-6 overflow-y-auto pb-10 custom-scrollbar">

              {activeFilter === 'PROFILE' && (
                <div className="grid md:grid-cols-2 gap-6 animate-in slide-in-from-right-4">
                  <div className="space-y-4">
                    <div>
                      <label className="text-[#AB1717] text-[9px] mb-1 block">RESIDENTIAL_LOC</label>
                      <p className="text-xl leading-none text-[#47510B]">{selectedCitizen.area}</p>
                      <p className="text-[10px] mt-1 opacity-50 italic uppercase">Sector 7, Block B, HYD-500081</p>
                    </div>
                    <div className="bg-white p-4 rounded-2xl border-[3px] border-[#47510B] space-y-3">
                       <div className="flex justify-between border-b border-[#47510B]/10 pb-2">
                          <span className="text-[9px] opacity-40">COMM_PHONE</span>
                          <span className="text-xs">{selectedCitizen.phone}</span>
                       </div>
                       <div className="flex justify-between">
                          <span className="text-[9px] opacity-40">STATUS_LVL</span>
                          <span className="text-[9px] bg-[#CAD23C] px-2 py-0.5 rounded text-[#47510B]">VERIFIED_OK</span>
                       </div>
                    </div>
                  </div>
                  <div className="bg-[#FFF24D] border-[3px] border-[#47510B] rounded-[24px] p-6 flex flex-col items-center justify-center text-center shadow-[4px_4px_0_0_#47510B]">
                     <ShieldCheck size={40} className="text-[#47510B] mb-2" />
                     <h3 className="text-lg text-[#47510B]">SECURE_ENTRY</h3>
                     <p className="text-[9px] opacity-60">GEOTAG_LOCKED // {selectedCitizen.zone}</p>
                  </div>
                </div>
              )}

              {activeFilter === 'REPORTS' && (
                <div className="space-y-2.5">
                  {citizenStats.reports.map(r => (
                    <div key={r.id} className="bg-white border-[2.5px] border-[#47510B] p-4 rounded-xl flex justify-between items-center shadow-[3px_3px_0_0_#CAD23C]">
                        <div>
                            <h4 className="text-sm">{r.type}</h4>
                            <p className="text-[8px] opacity-40">{r.id} // {r.date}</p>
                        </div>
                        <CheckCircle2 size={18} className="text-[#CAD23C]" />
                    </div>
                  ))}
                </div>
              )}

              {activeFilter === 'PENALTIES' && (
                <div className="space-y-2.5">
                  {citizenStats.penalties.map(p => (
                    <div key={p.id} className="bg-white border-[2.5px] border-[#AB1717] p-4 rounded-xl flex justify-between items-center shadow-[3px_3px_0_0_#AB1717]">
                        <h4 className="text-sm text-[#AB1717]">{p.reason}</h4>
                        <p className="text-xl text-[#AB1717]">{p.amount}</p>
                    </div>
                  ))}
                </div>
              )}

              {activeFilter === 'SCHEDULES' && (
                <div className="grid grid-cols-3 gap-3">
                  {citizenStats.schedules.map(s => (
                    <div key={s.day} className="bg-[#47510B] p-4 rounded-2xl text-white text-center border-2 border-[#FFF24D]">
                       <p className="text-[9px] opacity-60">{s.day}</p>
                       <p className="text-sm font-black">{s.time}</p>
                       <p className="text-[8px] mt-2 bg-[#FFF24D] text-[#47510B] rounded-full">{s.type}</p>
                    </div>
                  ))}
                </div>
              )}

              {activeFilter === 'SUBS' && (
                <div className="bg-[#FFF24D] border-[3px] border-[#47510B] p-6 rounded-3xl text-center shadow-[4px_4px_0_0_#A1AED1]">
                   <CreditCard size={32} className="mx-auto mb-2 text-[#47510B]" />
                   <h3 className="text-xl text-[#47510B]">{citizenStats.subscription.plan}</h3>
                   <p className="text-[9px] opacity-60">PRICE: {citizenStats.subscription.price} // RENEW: {citizenStats.subscription.expiry}</p>
                   <button className="mt-4 bg-[#47510B] text-white px-6 py-2 rounded-lg text-[9px]">MANAGE_SUBSCRIPTION</button>
                </div>
              )}

            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CitizensTab;
